package net.civeira.phylax.feature.identity.tenant.application.usecase.create;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.identity.tenant.domain.TenantChangeSet;

class TenantCreateInputUnitTest {

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the tenant input values are kept when converted to a change set and back")
  void test_tenant_create_input_change_set_round_trip() {
    TenantCreateInput input = TenantCreateInput.builder().uid("one").name("one").root(true)
        .domain("one").enabled(true).markForDelete(true).markForDeleteTime(LocalDateTime
            .of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime())
        .version(1).build();
    TenantChangeSet changes = input.toChangeSet();
    Assertions.assertNotNull(changes, "A change set must be created");
    TenantCreateInput copy = TenantCreateInput.fromChangeSet(changes);
    Assertions.assertTrue(input.getUid().isPresent(), "uid must be assigned by the builder");
    Assertions.assertEquals(input.getUid(), copy.getUid(),
        "uid must survive the change set round trip");
    Assertions.assertTrue(input.getName().isPresent(), "name must be assigned by the builder");
    Assertions.assertEquals(input.getName(), copy.getName(),
        "name must survive the change set round trip");
    Assertions.assertTrue(input.getRoot().isPresent(), "root must be assigned by the builder");
    Assertions.assertEquals(input.getRoot(), copy.getRoot(),
        "root must survive the change set round trip");
    Assertions.assertTrue(input.getDomain().isPresent(), "domain must be assigned by the builder");
    Assertions.assertEquals(input.getDomain(), copy.getDomain(),
        "domain must survive the change set round trip");
    Assertions.assertTrue(input.getEnabled().isPresent(),
        "enabled must be assigned by the builder");
    Assertions.assertEquals(input.getEnabled(), copy.getEnabled(),
        "enabled must survive the change set round trip");
    Assertions.assertTrue(input.getMarkForDelete().isPresent(),
        "markForDelete must be assigned by the builder");
    Assertions.assertEquals(input.getMarkForDelete(), copy.getMarkForDelete(),
        "markForDelete must survive the change set round trip");
    Assertions.assertTrue(input.getMarkForDeleteTime().isPresent(),
        "markForDeleteTime must be assigned by the builder");
    Assertions.assertEquals(input.getMarkForDeleteTime(), copy.getMarkForDeleteTime(),
        "markForDeleteTime must survive the change set round trip");
    Assertions.assertTrue(input.getVersion().isPresent(),
        "version must be assigned by the builder");
    Assertions.assertEquals(input.getVersion(), copy.getVersion(),
        "version must survive the change set round trip");
  }

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the tenant input builder can generate a new identifier")
  void test_tenant_create_input_new_uid() {
    TenantCreateInput input = TenantCreateInput.builder().newUid().build();
    Assertions.assertTrue(input.getUid().isPresent(), "A new uid must be generated");
    Assertions.assertTrue(input.getVersion().isPresent(), "The initial version must be assigned");
    Assertions.assertNotEquals(input.getUid(),
        TenantCreateInput.builder().newUid().build().getUid(), "Each new uid must be different");
  }

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the tenant input starts empty and the setters assign values")
  void test_tenant_create_input_setters() {
    TenantCreateInput empty = TenantCreateInput.builder().build();
    Assertions.assertTrue(empty.getUid().isEmpty(), "uid must be empty by default");
    Assertions.assertSame(empty, empty.setUid("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUid().isPresent(), "uid must be assigned by the setter");
    Assertions.assertTrue(empty.getName().isEmpty(), "name must be empty by default");
    Assertions.assertSame(empty, empty.setName("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getName().isPresent(), "name must be assigned by the setter");
    Assertions.assertTrue(empty.getRoot().isEmpty(), "root must be empty by default");
    Assertions.assertSame(empty, empty.setRoot(true), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getRoot().isPresent(), "root must be assigned by the setter");
    Assertions.assertTrue(empty.getDomain().isEmpty(), "domain must be empty by default");
    Assertions.assertSame(empty, empty.setDomain("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getDomain().isPresent(), "domain must be assigned by the setter");
    Assertions.assertTrue(empty.getEnabled().isEmpty(), "enabled must be empty by default");
    Assertions.assertSame(empty, empty.setEnabled(true), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getEnabled().isPresent(), "enabled must be assigned by the setter");
    Assertions.assertTrue(empty.getMarkForDelete().isEmpty(),
        "markForDelete must be empty by default");
    Assertions.assertSame(empty, empty.setMarkForDelete(true), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getMarkForDelete().isPresent(),
        "markForDelete must be assigned by the setter");
    Assertions.assertTrue(empty.getMarkForDeleteTime().isEmpty(),
        "markForDeleteTime must be empty by default");
    Assertions.assertSame(empty,
        empty.setMarkForDeleteTime(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime()),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getMarkForDeleteTime().isPresent(),
        "markForDeleteTime must be assigned by the setter");
    Assertions.assertTrue(empty.getVersion().isEmpty(), "version must be empty by default");
    Assertions.assertSame(empty, empty.setVersion(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getVersion().isPresent(), "version must be assigned by the setter");
    Assertions.assertNotNull(empty.toChangeSet(), "A change set must be created");
  }
}
